# Grammaire italienne, expliquée dans les autres langues d'interface.
T = {
'pronuncia': {
 'es': ('Pronunciación', "El italiano se lee como se escribe y todas las vocales se pronuncian.\nc y g ante e, i: «ch», «y» fuerte (cena, gelato); ante a, o, u: duras (casa, gatto). ch y gh ante e, i siguen duras (chiesa, spaghetti). ci, gi ante a, o, u: la i no se oye (ciao, giorno).\ngn = «ñ» (bagno). gli = «ll» palatal (figlio). sc ante e, i = «sh» (scena); sch = «sk» (scherzo). z = «ts» o «dz» (pizza, zero). h es muda.\nLas consonantes dobles se alargan y cambian el sentido: pala / palla, caro / carro.\nEl acento suele caer en la penúltima sílaba; solo se escribe en la última (città, perché).", ['Hola, ¿cómo estás?', 'Mi hijo come espaguetis.']),
 'de': ('Aussprache', "Italienisch wird gelesen, wie es geschrieben wird; alle Vokale werden ausgesprochen (u = „u“).\nc und g vor e, i: „tsch“, „dsch“ (cena, gelato); vor a, o, u: hart (casa, gatto). ch und gh vor e, i bleiben hart (chiesa, spaghetti). ci, gi vor a, o, u: das i hört man nicht (ciao, giorno).\ngn = „nj“ (bagno). gli = weiches „lj“ (figlio). sc vor e, i = „sch“ (scena); sch = „sk“ (scherzo). z = „ts“ oder „ds“ (pizza, zero). h ist stumm.\nDoppelkonsonanten werden länger gehalten und ändern die Bedeutung: pala / palla, caro / carro.\nDie Betonung liegt meist auf der vorletzten Silbe; geschrieben wird der Akzent nur auf der letzten (città, perché).", ['Hallo, wie geht es dir?', 'Mein Sohn isst Spaghetti.']),
 'pt': ('Pronúncia', "O italiano lê-se como se escreve e todas as vogais se pronunciam.\nc e g antes de e, i: «tch», «dj» (cena, gelato); antes de a, o, u: duros (casa, gatto). ch e gh antes de e, i continuam duros (chiesa, spaghetti). ci, gi antes de a, o, u: o i não se ouve (ciao, giorno).\ngn = «nh» (bagno). gli = «lh» (figlio). sc antes de e, i = «ch» português (scena); sch = «sk» (scherzo). z = «ts» ou «dz» (pizza, zero). h é mudo.\nConsoantes dobradas são mais longas e mudam o sentido: pala / palla, caro / carro.\nO acento cai quase sempre na penúltima sílaba; só se escreve na última (città, perché).", ['Oi, tudo bem?', 'Meu filho come espaguete.']),
 'ja': ('発音', "イタリア語は書いた通りに読み、母音はすべて発音します。\ne, i の前の c, g は「チ」「ジ」（cena, gelato）、a, o, u の前では「カ」「ガ」行（casa, gatto）。e, i の前の ch, gh は「キ」「ギ」（chiesa, spaghetti）。a, o, u の前の ci, gi は i を読みません（ciao, giorno）。\ngn は「ニャ」行（bagno）。gli は「リャ」行に近い音（figlio）。e, i の前の sc は「シ」（scena）、sch は「スク」（scherzo）。z は「ツ」か「ズ」（pizza, zero）。h は読みません。\n二重子音は長く発音し、意味が変わります：pala / palla, caro / carro。\nアクセントはたいてい後ろから二番目の音節。最後の音節にあるときだけ記号を書きます（città, perché）。", ['やあ、元気？', '息子はスパゲッティを食べています。']),
 'zh': ('发音', "意大利语怎么写就怎么读，所有元音都要发音。\ne, i 前的 c、g 读「q」「j」（cena, gelato）；a, o, u 前读硬音（casa, gatto）。e, i 前的 ch、gh 仍读硬音（chiesa, spaghetti）。a, o, u 前的 ci、gi 中 i 不发音（ciao, giorno）。\ngn 读「ny」（bagno）。gli 读软「ly」（figlio）。e, i 前的 sc 读「sh」（scena）；sch 读「sk」（scherzo）。z 读「ts」或「dz」（pizza, zero）。h 不发音。\n双辅音要读得长一些，会改变词义：pala / palla，caro / carro。\n重音多在倒数第二个音节；只有在最后一个音节时才写出来（città, perché）。", ['嗨，你好吗？', '我儿子在吃意大利面。']),
 'ko': ('발음', "이탈리아어는 쓰인 대로 읽고 모음은 모두 발음합니다.\ne, i 앞의 c, g는 「치」, 「지」(cena, gelato), a, o, u 앞에서는 「ㅋ」, 「ㄱ」(casa, gatto). e, i 앞의 ch, gh는 「키」, 「기」(chiesa, spaghetti). a, o, u 앞의 ci, gi는 i를 읽지 않습니다(ciao, giorno).\ngn은 「냐」 줄(bagno). gli는 부드러운 「리」(figlio). e, i 앞의 sc는 「시」(scena), sch는 「스크」(scherzo). z는 「ㅊ」나 「ㅈ」(pizza, zero). h는 읽지 않습니다.\n겹자음은 길게 발음하며 뜻이 달라집니다: pala / palla, caro / carro.\n강세는 보통 끝에서 두 번째 음절이며, 마지막 음절일 때만 표시합니다(città, perché).", ['안녕, 잘 지내?', '아들이 스파게티를 먹어요.']),
 'lt': ('Tarimas', "Itališkai skaitoma, kaip rašoma, tariami visi balsiai.\nc ir g prieš e, i: „č“, „dž“ (cena, gelato); prieš a, o, u: kieti (casa, gatto). ch ir gh prieš e, i lieka kieti (chiesa, spaghetti). ci, gi prieš a, o, u: i negirdimas (ciao, giorno).\ngn = „nj“ (bagno). gli = minkštas „lj“ (figlio). sc prieš e, i = „š“ (scena); sch = „sk“ (scherzo). z = „c“ arba „dz“ (pizza, zero). h netariama.\nDvigubi priebalsiai tariami ilgiau ir keičia reikšmę: pala / palla, caro / carro.\nKirtis dažniausiai priešpaskutiniame skiemenyje; rašomas tik paskutiniame (città, perché).", ['Labas, kaip sekasi?', 'Mano sūnus valgo spagečius.']),
 'tl': ('Pagbigkas', "Binabasa ang Italyano kung paano isinulat; binibigkas ang lahat ng patinig.\nc at g bago ang e, i: «ts», «dy» (cena, gelato); bago ang a, o, u: matigas (casa, gatto). ch at gh bago ang e, i: matigas pa rin (chiesa, spaghetti). ci, gi bago ang a, o, u: hindi naririnig ang i (ciao, giorno).\ngn = «ny» (bagno). gli = malambot na «ly» (figlio). sc bago ang e, i = «sh» (scena); sch = «sk» (scherzo). z = «ts» o «dz» (pizza, zero). Walang tunog ang h.\nPinahahaba ang dobleng katinig at nag-iiba ang kahulugan: pala / palla, caro / carro.\nKaraniwang nasa ikalawa mula sa huli ang diin; isinusulat lang kapag nasa huli (città, perché).", ['Hi, kumusta ka?', 'Kumakain ng spaghetti ang anak ko.']),
},
'articles': {
 'es': ('El género y los artículos', "Masculino en -o (plural -i), femenino en -a (plural -e); los sustantivos en -e pueden ser de uno u otro género (plural -i): il libro → i libri, la casa → le case, il fiore → i fiori.\nArtículos definidos: il / i; lo / gli ante s + consonante, z, gn, ps (lo studente, gli studenti); l' ante vocal (l'amico, gli amici); la / le (l'amica, le amiche).\nIndefinidos: un, uno, una, un'.", ['El libro está en la mesa.', 'Los estudiantes están en clase.']),
 'de': ('Genus und Artikel', "Maskulin auf -o (Plural -i), feminin auf -a (Plural -e); Nomen auf -e können beides sein (Plural -i): il libro → i libri, la casa → le case, il fiore → i fiori.\nBestimmte Artikel: il / i; lo / gli vor s + Konsonant, z, gn, ps (lo studente, gli studenti); l' vor Vokal (l'amico, gli amici); la / le (l'amica, le amiche).\nUnbestimmte: un, uno, una, un'.", ['Das Buch liegt auf dem Tisch.', 'Die Studenten sind im Unterricht.']),
 'pt': ('O gênero e os artigos', "Masculino em -o (plural -i), feminino em -a (plural -e); os substantivos em -e podem ser de um ou outro gênero (plural -i): il libro → i libri, la casa → le case, il fiore → i fiori.\nArtigos definidos: il / i; lo / gli antes de s + consoante, z, gn, ps (lo studente, gli studenti); l' antes de vogal (l'amico, gli amici); la / le (l'amica, le amiche).\nIndefinidos: un, uno, una, un'.", ['O livro está na mesa.', 'Os estudantes estão na aula.']),
 'ja': ('名詞の性と冠詞', "男性は -o（複数 -i）、女性は -a（複数 -e）。-e で終わる名詞はどちらもあり、複数は -i：il libro → i libri, la casa → le case, il fiore → i fiori。\n定冠詞：il / i。s + 子音・z・gn・ps の前は lo / gli（lo studente, gli studenti）。母音の前は l'（l'amico, gli amici）。女性は la / le（l'amica, le amiche）。\n不定冠詞：un, uno, una, un'。", ['本はテーブルの上にあります。', '学生たちは教室にいます。']),
 'zh': ('名词的性与冠词', "阳性以 -o 结尾（复数 -i），阴性以 -a 结尾（复数 -e）；以 -e 结尾的名词可阴可阳（复数 -i）：il libro → i libri，la casa → le case，il fiore → i fiori。\n定冠词：il / i；在 s + 辅音、z、gn、ps 前用 lo / gli（lo studente, gli studenti）；元音前用 l'（l'amico, gli amici）；阴性 la / le（l'amica, le amiche）。\n不定冠词：un, uno, una, un'。", ['书在桌子上。', '学生们在上课。']),
 'ko': ('명사의 성과 관사', "남성은 -o(복수 -i), 여성은 -a(복수 -e)로 끝납니다. -e로 끝나는 명사는 둘 다 가능하며 복수는 -i입니다: il libro → i libri, la casa → le case, il fiore → i fiori.\n정관사: il / i, s + 자음, z, gn, ps 앞에서는 lo / gli(lo studente, gli studenti), 모음 앞에서는 l'(l'amico, gli amici), 여성은 la / le(l'amica, le amiche).\n부정관사: un, uno, una, un'.", ['책은 탁자 위에 있어요.', '학생들은 교실에 있어요.']),
 'lt': ('Giminė ir artikeliai', "Vyriškoji giminė baigiasi -o (daugiskaita -i), moteriškoji -a (daugiskaita -e); daiktavardžiai su -e gali būti abiejų giminių (daugiskaita -i): il libro → i libri, la casa → le case, il fiore → i fiori.\nŽymimieji artikeliai: il / i; lo / gli prieš s + priebalsį, z, gn, ps (lo studente, gli studenti); l' prieš balsį (l'amico, gli amici); la / le (l'amica, le amiche).\nNežymimieji: un, uno, una, un'.", ['Knyga ant stalo.', 'Studentai yra klasėje.']),
 'tl': ('Kasarian at mga pantukoy', "Panlalaki sa -o (maramihan -i), pambabae sa -a (maramihan -e); ang mga pangngalang nagtatapos sa -e ay puwedeng alinman (maramihan -i): il libro → i libri, la casa → le case, il fiore → i fiori.\nTiyak na pantukoy: il / i; lo / gli bago ang s + katinig, z, gn, ps (lo studente, gli studenti); l' bago patinig (l'amico, gli amici); la / le (l'amica, le amiche).\nDi-tiyak: un, uno, una, un'.", ['Nasa mesa ang libro.', 'Nasa klase ang mga estudyante.']),
},
'essere-avere': {
 'es': ('Essere y avere', "essere: sono, sei, è, siamo, siete, sono. avere: ho, hai, ha, abbiamo, avete, hanno (la h no se pronuncia).\nEl pronombre sujeto suele omitirse. «C'è» + singular, «ci sono» + plural = hay.\nCon avere: ho fame, ho sete, ho vent'anni, ho freddo, ho ragione.", ['Soy italiano.', 'Tengo dos hermanos.', 'Hay un problema.']),
 'de': ('Essere und avere', "essere (sein): sono, sei, è, siamo, siete, sono. avere (haben): ho, hai, ha, abbiamo, avete, hanno (das h ist stumm).\nDas Subjektpronomen fällt meist weg. „C'è“ + Singular, „ci sono“ + Plural = es gibt.\nMit avere: ho fame (ich habe Hunger), ho sete, ho vent'anni (ich bin zwanzig), ho freddo, ho ragione.", ['Ich bin Italiener.', 'Ich habe zwei Brüder.', 'Es gibt ein Problem.']),
 'pt': ('Essere e avere', "essere (ser / estar): sono, sei, è, siamo, siete, sono. avere (ter): ho, hai, ha, abbiamo, avete, hanno (o h não se pronuncia).\nO pronome sujeito costuma ser omitido. «C'è» + singular, «ci sono» + plural = há.\nCom avere: ho fame, ho sete, ho vent'anni, ho freddo, ho ragione.", ['Sou italiano.', 'Tenho dois irmãos.', 'Há um problema.']),
 'ja': ('essere と avere', "essere（〜である）：sono, sei, è, siamo, siete, sono。avere（持つ）：ho, hai, ha, abbiamo, avete, hanno（h は読みません）。\n主語の代名詞はふつう省略します。c'è + 単数、ci sono + 複数 = 〜がある。\navere を使う表現：ho fame（お腹がすいた）、ho sete、ho vent'anni（20歳だ）、ho freddo、ho ragione。", ['私はイタリア人です。', '兄弟が二人います。', '問題があります。']),
 'zh': ('essere 与 avere', "essere（是）：sono, sei, è, siamo, siete, sono。avere（有）：ho, hai, ha, abbiamo, avete, hanno（h 不发音）。\n主语代词通常省略。c'è + 单数，ci sono + 复数 = 有。\n用 avere 的表达：ho fame（饿了），ho sete，ho vent'anni（二十岁），ho freddo，ho ragione。", ['我是意大利人。', '我有两个兄弟。', '有一个问题。']),
 'ko': ('essere와 avere', "essere(~이다): sono, sei, è, siamo, siete, sono. avere(가지다): ho, hai, ha, abbiamo, avete, hanno(h는 읽지 않습니다).\n주어 대명사는 보통 생략합니다. c'è + 단수, ci sono + 복수 = ~이 있다.\navere를 쓰는 표현: ho fame(배고프다), ho sete, ho vent'anni(스무 살이다), ho freddo, ho ragione.", ['저는 이탈리아 사람이에요.', '형제가 둘 있어요.', '문제가 있어요.']),
 'lt': ('Essere ir avere', "essere (būti): sono, sei, è, siamo, siete, sono. avere (turėti): ho, hai, ha, abbiamo, avete, hanno (h netariama).\nAsmeninis įvardis paprastai praleidžiamas. „C'è“ + vienaskaita, „ci sono“ + daugiskaita = yra.\nSu avere: ho fame (esu alkanas), ho sete, ho vent'anni (man dvidešimt), ho freddo, ho ragione.", ['Aš italas.', 'Turiu du brolius.', 'Yra problema.']),
 'tl': ('Essere at avere', "essere (maging): sono, sei, è, siamo, siete, sono. avere (magkaroon): ho, hai, ha, abbiamo, avete, hanno (walang tunog ang h).\nKaraniwang hindi na sinasabi ang panghalip. «C'è» + isahan, «ci sono» + maramihan = mayroon.\nGamit ang avere: ho fame (gutom ako), ho sete, ho vent'anni (dalawampung taon ako), ho freddo, ho ragione.", ['Italyano ako.', 'May dalawa akong kapatid na lalaki.', 'May problema.']),
},
'present': {
 'es': ('El presente de los verbos regulares', "parlare: parlo, parli, parla, parliamo, parlate, parlano.\nprendere: prendo, prendi, prende, prendiamo, prendete, prendono.\ndormire: dormo, dormi, dorme, dormiamo, dormite, dormono. Algunos verbos en -ire intercalan -isc-: finisco, finisci, finisce, finiamo, finite, finiscono (capire, preferire).\nNegación: «non» delante del verbo.", ['Hablo italiano.', 'No entiendo.']),
 'de': ('Das Präsens der regelmäßigen Verben', "parlare: parlo, parli, parla, parliamo, parlate, parlano.\nprendere: prendo, prendi, prende, prendiamo, prendete, prendono.\ndormire: dormo, dormi, dorme, dormiamo, dormite, dormono. Manche Verben auf -ire schieben -isc- ein: finisco, finisci, finisce, finiamo, finite, finiscono (capire, preferire).\nVerneinung: „non“ vor dem Verb.", ['Ich spreche Italienisch.', 'Ich verstehe nicht.']),
 'pt': ('O presente dos verbos regulares', "parlare: parlo, parli, parla, parliamo, parlate, parlano.\nprendere: prendo, prendi, prende, prendiamo, prendete, prendono.\ndormire: dormo, dormi, dorme, dormiamo, dormite, dormono. Alguns verbos em -ire intercalam -isc-: finisco, finisci, finisce, finiamo, finite, finiscono (capire, preferire).\nNegação: «non» antes do verbo.", ['Falo italiano.', 'Não entendo.']),
 'ja': ('規則動詞の現在形', "parlare：parlo, parli, parla, parliamo, parlate, parlano。\nprendere：prendo, prendi, prende, prendiamo, prendete, prendono。\ndormire：dormo, dormi, dorme, dormiamo, dormite, dormono。-ire 動詞の一部は -isc- が入ります：finisco, finisci, finisce, finiamo, finite, finiscono（capire, preferire）。\n否定：動詞の前に「non」。", ['イタリア語を話します。', 'わかりません。']),
 'zh': ('规则动词的现在时', "parlare：parlo, parli, parla, parliamo, parlate, parlano。\nprendere：prendo, prendi, prende, prendiamo, prendete, prendono。\ndormire：dormo, dormi, dorme, dormiamo, dormite, dormono。部分 -ire 动词插入 -isc-：finisco, finisci, finisce, finiamo, finite, finiscono（capire, preferire）。\n否定：在动词前加「non」。", ['我说意大利语。', '我不明白。']),
 'ko': ('규칙 동사의 현재형', "parlare: parlo, parli, parla, parliamo, parlate, parlano.\nprendere: prendo, prendi, prende, prendiamo, prendete, prendono.\ndormire: dormo, dormi, dorme, dormiamo, dormite, dormono. 일부 -ire 동사는 -isc-가 들어갑니다: finisco, finisci, finisce, finiamo, finite, finiscono(capire, preferire).\n부정: 동사 앞에 「non」.", ['저는 이탈리아어를 해요.', '이해가 안 돼요.']),
 'lt': ('Taisyklingųjų veiksmažodžių esamasis laikas', "parlare: parlo, parli, parla, parliamo, parlate, parlano.\nprendere: prendo, prendi, prende, prendiamo, prendete, prendono.\ndormire: dormo, dormi, dorme, dormiamo, dormite, dormono. Kai kurie -ire veiksmažodžiai įterpia -isc-: finisco, finisci, finisce, finiamo, finite, finiscono (capire, preferire).\nNeiginys: „non“ prieš veiksmažodį.", ['Kalbu itališkai.', 'Nesuprantu.']),
 'tl': ('Kasalukuyan ng regular na pandiwa', "parlare: parlo, parli, parla, parliamo, parlate, parlano.\nprendere: prendo, prendi, prende, prendiamo, prendete, prendono.\ndormire: dormo, dormi, dorme, dormiamo, dormite, dormono. May mga pandiwang -ire na sinisingitan ng -isc-: finisco, finisci, finisce, finiamo, finite, finiscono (capire, preferire).\nNegatibo: «non» bago ang pandiwa.", ['Nagsasalita ako ng Italyano.', 'Hindi ko maintindihan.']),
},
'irreguliers': {
 'es': ('Presente: verbos irregulares frecuentes', "andare: vado, vai, va, andiamo, andate, vanno. fare: faccio, fai, fa, facciamo, fate, fanno. venire: vengo, vieni, viene. dire: dico, dici, dice. stare: sto, stai, sta. dare: do, dai, dà. sapere: so, sai, sa. uscire: esco, esci, esce.\nModales: potere (posso, puoi, può), volere (voglio, vuoi, vuole), dovere (devo, devi, deve), seguidos del infinitivo.", ['Voy a casa.', '¿Qué haces?', '¿Puedo entrar?']),
 'de': ('Präsens: häufige unregelmäßige Verben', "andare: vado, vai, va, andiamo, andate, vanno. fare: faccio, fai, fa, facciamo, fate, fanno. venire: vengo, vieni, viene. dire: dico, dici, dice. stare: sto, stai, sta. dare: do, dai, dà. sapere: so, sai, sa. uscire: esco, esci, esce.\nModalverben: potere (posso, puoi, può), volere (voglio, vuoi, vuole), dovere (devo, devi, deve), mit Infinitiv.", ['Ich gehe nach Hause.', 'Was machst du?', 'Darf ich hereinkommen?']),
 'pt': ('Presente: verbos irregulares frequentes', "andare: vado, vai, va, andiamo, andate, vanno. fare: faccio, fai, fa, facciamo, fate, fanno. venire: vengo, vieni, viene. dire: dico, dici, dice. stare: sto, stai, sta. dare: do, dai, dà. sapere: so, sai, sa. uscire: esco, esci, esce.\nModais: potere (posso, puoi, può), volere (voglio, vuoi, vuole), dovere (devo, devi, deve), seguidos do infinitivo.", ['Vou para casa.', 'O que você está fazendo?', 'Posso entrar?']),
 'ja': ('現在形：よく使う不規則動詞', "andare：vado, vai, va, andiamo, andate, vanno。fare：faccio, fai, fa, facciamo, fate, fanno。venire：vengo, vieni, viene。dire：dico, dici, dice。stare：sto, stai, sta。dare：do, dai, dà。sapere：so, sai, sa。uscire：esco, esci, esce。\n助動詞的な動詞：potere（posso, puoi, può）、volere（voglio, vuoi, vuole）、dovere（devo, devi, deve）。後ろに不定詞を置きます。", ['家に帰ります。', '何してるの？', '入ってもいいですか？']),
 'zh': ('现在时：常用不规则动词', "andare：vado, vai, va, andiamo, andate, vanno。fare：faccio, fai, fa, facciamo, fate, fanno。venire：vengo, vieni, viene。dire：dico, dici, dice。stare：sto, stai, sta。dare：do, dai, dà。sapere：so, sai, sa。uscire：esco, esci, esce。\n情态动词：potere（posso, puoi, può），volere（voglio, vuoi, vuole），dovere（devo, devi, deve），后接不定式。", ['我回家。', '你在做什么？', '我可以进来吗？']),
 'ko': ('현재형: 자주 쓰는 불규칙 동사', "andare: vado, vai, va, andiamo, andate, vanno. fare: faccio, fai, fa, facciamo, fate, fanno. venire: vengo, vieni, viene. dire: dico, dici, dice. stare: sto, stai, sta. dare: do, dai, dà. sapere: so, sai, sa. uscire: esco, esci, esce.\n조동사: potere(posso, puoi, può), volere(voglio, vuoi, vuole), dovere(devo, devi, deve) 뒤에 동사원형이 옵니다.", ['집에 가요.', '뭐 해?', '들어가도 될까요?']),
 'lt': ('Esamasis laikas: dažni netaisyklingi veiksmažodžiai', "andare: vado, vai, va, andiamo, andate, vanno. fare: faccio, fai, fa, facciamo, fate, fanno. venire: vengo, vieni, viene. dire: dico, dici, dice. stare: sto, stai, sta. dare: do, dai, dà. sapere: so, sai, sa. uscire: esco, esci, esce.\nModaliniai: potere (posso, puoi, può), volere (voglio, vuoi, vuole), dovere (devo, devi, deve), su bendratimi.", ['Einu namo.', 'Ką darai?', 'Ar galiu įeiti?']),
 'tl': ('Kasalukuyan: madalas na di-regular', "andare: vado, vai, va, andiamo, andate, vanno. fare: faccio, fai, fa, facciamo, fate, fanno. venire: vengo, vieni, viene. dire: dico, dici, dice. stare: sto, stai, sta. dare: do, dai, dà. sapere: so, sai, sa. uscire: esco, esci, esce.\nMga modal: potere (posso, puoi, può), volere (voglio, vuoi, vuole), dovere (devo, devi, deve), sinusundan ng infinitive.", ['Uuwi na ako.', 'Ano ang ginagawa mo?', 'Puwede ba akong pumasok?']),
},
'adjectifs': {
 'es': ('El adjetivo y los posesivos', "El adjetivo concuerda: rosso, rossa, rossi, rosse; los terminados en -e tienen dos formas (grande, grandi). Suele ir detrás del sustantivo: una macchina rossa.\nLos posesivos llevan artículo: il mio libro, la tua casa, i suoi amici. Sin artículo con un nombre de parentesco en singular: mia madre, tuo fratello (pero i miei genitori).", ['Mi casa es pequeña.', 'Mi padre es médico.']),
 'de': ('Adjektiv und Possessivbegleiter', "Das Adjektiv wird angeglichen: rosso, rossa, rossi, rosse; Adjektive auf -e haben zwei Formen (grande, grandi). Es steht meist nach dem Nomen: una macchina rossa.\nPossessivbegleiter stehen mit Artikel: il mio libro, la tua casa, i suoi amici. Kein Artikel bei Verwandtschaftsnamen im Singular: mia madre, tuo fratello (aber i miei genitori).", ['Mein Haus ist klein.', 'Mein Vater ist Arzt.']),
 'pt': ('O adjetivo e os possessivos', "O adjetivo concorda: rosso, rossa, rossi, rosse; os terminados em -e têm duas formas (grande, grandi). Costuma vir depois do substantivo: una macchina rossa.\nOs possessivos levam artigo: il mio libro, la tua casa, i suoi amici. Sem artigo com nome de parentesco no singular: mia madre, tuo fratello (mas i miei genitori).", ['Minha casa é pequena.', 'Meu pai é médico.']),
 'ja': ('形容詞と所有詞', "形容詞は性数を合わせます：rosso, rossa, rossi, rosse。-e で終わる形容詞は二つの形（grande, grandi）。ふつう名詞の後に置きます：una macchina rossa。\n所有詞には冠詞をつけます：il mio libro, la tua casa, i suoi amici。ただし単数の親族名詞には冠詞をつけません：mia madre, tuo fratello（複数は i miei genitori）。", ['私の家は小さいです。', '父は医者です。']),
 'zh': ('形容词与物主形容词', "形容词要配合性数：rosso, rossa, rossi, rosse；以 -e 结尾的形容词有两种形式（grande, grandi）。通常放在名词后：una macchina rossa。\n物主形容词前加冠词：il mio libro, la tua casa, i suoi amici。单数亲属名词前不加冠词：mia madre, tuo fratello（但复数 i miei genitori）。", ['我的房子很小。', '我父亲是医生。']),
 'ko': ('형용사와 소유사', "형용사는 성과 수를 맞춥니다: rosso, rossa, rossi, rosse. -e로 끝나는 형용사는 두 형태(grande, grandi). 보통 명사 뒤에 둡니다: una macchina rossa.\n소유사는 관사와 함께 씁니다: il mio libro, la tua casa, i suoi amici. 단수 친족 명사에는 관사를 쓰지 않습니다: mia madre, tuo fratello(복수는 i miei genitori).", ['우리 집은 작아요.', '아버지는 의사예요.']),
 'lt': ('Būdvardis ir savybiniai žodžiai', "Būdvardis derinamas: rosso, rossa, rossi, rosse; būdvardžiai su -e turi dvi formas (grande, grandi). Paprastai eina po daiktavardžio: una macchina rossa.\nSavybiniai vartojami su artikeliu: il mio libro, la tua casa, i suoi amici. Be artikelio su giminystės daiktavardžiu vienaskaitoje: mia madre, tuo fratello (bet i miei genitori).", ['Mano namas mažas.', 'Mano tėvas gydytojas.']),
 'tl': ('Pang-uri at paari', "Tumutugma ang pang-uri: rosso, rossa, rossi, rosse; dalawa ang anyo ng nagtatapos sa -e (grande, grandi). Karaniwang sumusunod sa pangngalan: una macchina rossa.\nMay pantukoy ang mga paari: il mio libro, la tua casa, i suoi amici. Walang pantukoy sa kamag-anak na isahan: mia madre, tuo fratello (pero i miei genitori).", ['Maliit ang bahay ko.', 'Doktor ang tatay ko.']),
},
'prepositions': {
 'es': ('Las preposiciones y sus contracciones', "a (a), di (de), da (desde, de casa de, por), in (en), su (sobre), con, per, tra / fra.\nSe funden con el artículo: a + il = al, di + il = del, da + il = dal, in + il = nel, su + il = sul; igualmente allo, alla, ai, agli, alle; della, nella, sulla…\nCiudades: a Roma; países: in Italia. En casa de alguien: da Maria.", ['Voy al cine.', 'Vivo en Italia desde hace dos años.']),
 'de': ('Präpositionen und ihre Verschmelzungen', "a (nach, zu, in), di (von), da (von, seit, bei), in (in), su (auf), con, per, tra / fra.\nSie verschmelzen mit dem Artikel: a + il = al, di + il = del, da + il = dal, in + il = nel, su + il = sul; ebenso allo, alla, ai, agli, alle; della, nella, sulla…\nStädte: a Roma; Länder: in Italia. Bei jemandem: da Maria.", ['Ich gehe ins Kino.', 'Ich lebe seit zwei Jahren in Italien.']),
 'pt': ('As preposições e suas contrações', "a (a), di (de), da (desde, da casa de, por), in (em), su (sobre), con, per, tra / fra.\nFundem-se com o artigo: a + il = al, di + il = del, da + il = dal, in + il = nel, su + il = sul; também allo, alla, ai, agli, alle; della, nella, sulla…\nCidades: a Roma; países: in Italia. Na casa de alguém: da Maria.", ['Vou ao cinema.', 'Moro na Itália há dois anos.']),
 'ja': ('前置詞とその結合形', "a（〜へ、〜に）、di（〜の）、da（〜から、〜の家で、〜によって）、in（〜の中に）、su（〜の上に）、con、per、tra / fra。\n定冠詞と結合します：a + il = al、di + il = del、da + il = dal、in + il = nel、su + il = sul。同様に allo, alla, ai, agli, alle、della, nella, sulla…\n都市には a（a Roma）、国には in（in Italia）。人の家では da（da Maria）。", ['映画館に行きます。', 'イタリアに住んで2年になります。']),
 'zh': ('介词及其缩合形式', "a（到、在），di（……的），da（从、在某人家、由），in（在……里），su（在……上），con，per，tra / fra。\n与冠词缩合：a + il = al，di + il = del，da + il = dal，in + il = nel，su + il = sul；同理 allo, alla, ai, agli, alle；della, nella, sulla……\n城市用 a（a Roma），国家用 in（in Italia）。在某人家：da Maria。", ['我去电影院。', '我在意大利住了两年了。']),
 'ko': ('전치사와 결합형', "a(~에, ~로), di(~의), da(~로부터, ~의 집에, ~에 의해), in(~안에), su(~위에), con, per, tra / fra.\n관사와 합쳐집니다: a + il = al, di + il = del, da + il = dal, in + il = nel, su + il = sul, 마찬가지로 allo, alla, ai, agli, alle, della, nella, sulla…\n도시는 a(a Roma), 나라는 in(in Italia). 누구의 집에: da Maria.", ['영화관에 가요.', '이탈리아에 산 지 2년 됐어요.']),
 'lt': ('Prielinksniai ir jų sutraukimai', "a (į, -e), di (-o, iš), da (nuo, pas, iš), in (į, -e), su (ant), con, per, tra / fra.\nJie susilieja su artikeliu: a + il = al, di + il = del, da + il = dal, in + il = nel, su + il = sul; taip pat allo, alla, ai, agli, alle; della, nella, sulla…\nMiestai: a Roma; šalys: in Italia. Pas ką nors: da Maria.", ['Einu į kiną.', 'Gyvenu Italijoje jau dvejus metus.']),
 'tl': ('Mga pang-ukol at ang pagsasama nila', "a (sa, papunta), di (ng), da (mula, sa bahay ni, ni), in (sa loob), su (sa ibabaw), con, per, tra / fra.\nSumasama sa pantukoy: a + il = al, di + il = del, da + il = dal, in + il = nel, su + il = sul; gayundin allo, alla, ai, agli, alle; della, nella, sulla…\nLungsod: a Roma; bansa: in Italia. Sa bahay ng isang tao: da Maria.", ['Manonood ako ng sine.', 'Dalawang taon na akong nakatira sa Italya.']),
},
'questions': {
 'es': ('Hacer una pregunta', "El orden de las palabras no cambia; solo sube la entonación: Parli inglese?\nPalabras interrogativas: che cosa / cosa (qué), chi (quién), dove (dónde), quando, come, perché (por qué y porque), quanto, quale.", ['¿Dónde vives?', '¿Cuánto cuesta?']),
 'de': ('Fragen stellen', "Die Wortstellung ändert sich nicht; nur die Stimme steigt: Parli inglese?\nFragewörter: che cosa / cosa (was), chi (wer), dove (wo), quando (wann), come (wie), perché (warum und weil), quanto (wie viel), quale (welcher).", ['Wo wohnst du?', 'Wie viel kostet das?']),
 'pt': ('Fazer uma pergunta', "A ordem das palavras não muda; só a entonação sobe: Parli inglese?\nPalavras interrogativas: che cosa / cosa (o que), chi (quem), dove (onde), quando, come (como), perché (por que e porque), quanto, quale (qual).", ['Onde você mora?', 'Quanto custa?']),
 'ja': ('疑問文の作り方', "語順は変わらず、イントネーションを上げるだけです：Parli inglese?\n疑問詞：che cosa / cosa（何）、chi（誰）、dove（どこ）、quando（いつ）、come（どのように）、perché（なぜ／なぜなら）、quanto（いくつ、いくら）、quale（どれ）。", ['どこに住んでいるの？', 'いくらですか？']),
 'zh': ('提问', "语序不变，只要语调上扬：Parli inglese?\n疑问词：che cosa / cosa（什么），chi（谁），dove（哪里），quando（什么时候），come（怎样），perché（为什么，也表示因为），quanto（多少），quale（哪个）。", ['你住在哪儿？', '多少钱？']),
 'ko': ('질문하기', "어순은 그대로이고 억양만 올립니다: Parli inglese?\n의문사: che cosa / cosa(무엇), chi(누구), dove(어디), quando(언제), come(어떻게), perché(왜, 그리고 '왜냐하면'), quanto(얼마), quale(어느 것).", ['어디 살아요?', '얼마예요?']),
 'lt': ('Klausimo uždavimas', "Žodžių tvarka nesikeičia; tik pakyla intonacija: Parli inglese?\nKlausiamieji žodžiai: che cosa / cosa (kas), chi (kas – asmuo), dove (kur), quando (kada), come (kaip), perché (kodėl ir nes), quanto (kiek), quale (kuris).", ['Kur tu gyveni?', 'Kiek kainuoja?']),
 'tl': ('Pagtatanong', "Hindi nagbabago ang ayos ng salita; tumataas lang ang tono: Parli inglese?\nMga salitang pananong: che cosa / cosa (ano), chi (sino), dove (saan), quando (kailan), come (paano), perché (bakit at dahil), quanto (magkano, ilan), quale (alin).", ['Saan ka nakatira?', 'Magkano ito?']),
},
'passato-prossimo': {
 'es': ('El pretérito perfecto (passato prossimo)', "avere o essere en presente + participio (-ato, -uto, -ito: parlato, venduto, dormito).\n«Essere» con los verbos de movimiento y de estado (andare, venire, partire, nascere, restare) y con los pronominales; el participio concuerda entonces con el sujeto: Maria è andata.\nParticipios irregulares: fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso.\nEs el pasado habitual en el norte de Italia, incluso para hechos de ayer.", ['Comí una pizza.', 'Fuimos al mar.']),
 'de': ('Das Perfekt (passato prossimo)', "avere oder essere im Präsens + Partizip (-ato, -uto, -ito: parlato, venduto, dormito).\n„Essere“ bei Verben der Bewegung und des Zustands (andare, venire, partire, nascere, restare) und bei reflexiven Verben; das Partizip richtet sich dann nach dem Subjekt: Maria è andata.\nUnregelmäßige Partizipien: fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso.", ['Ich habe eine Pizza gegessen.', 'Wir sind ans Meer gefahren.']),
 'pt': ('O passato prossimo', "avere ou essere no presente + particípio (-ato, -uto, -ito: parlato, venduto, dormito). Corresponde ao pretérito perfeito português (comi, fui).\n«Essere» com verbos de movimento e de estado (andare, venire, partire, nascere, restare) e com os pronominais; o particípio concorda então com o sujeito: Maria è andata.\nParticípios irregulares: fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso.", ['Comi uma pizza.', 'Fomos à praia.']),
 'ja': ('近過去', "avere または essere の現在形 + 過去分詞（-ato, -uto, -ito：parlato, venduto, dormito）。\n移動や状態を表す動詞（andare, venire, partire, nascere, restare）と再帰動詞は essere を使い、過去分詞は主語の性数に合わせます：Maria è andata。\n不規則な過去分詞：fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso。", ['ピザを食べました。', '私たちは海へ行きました。']),
 'zh': ('近过去时', "avere 或 essere 的现在时 + 过去分词（-ato, -uto, -ito：parlato, venduto, dormito）。\n表示位移和状态的动词（andare, venire, partire, nascere, restare）以及自反动词用 essere，此时过去分词与主语性数一致：Maria è andata。\n不规则过去分词：fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso。", ['我吃了一个比萨。', '我们去了海边。']),
 'ko': ('근과거', "avere 또는 essere 현재형 + 과거분사(-ato, -uto, -ito: parlato, venduto, dormito).\n이동과 상태를 나타내는 동사(andare, venire, partire, nascere, restare)와 재귀 동사는 essere를 쓰고, 과거분사를 주어의 성과 수에 맞춥니다: Maria è andata.\n불규칙 과거분사: fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso.", ['피자를 먹었어요.', '우리는 바다에 갔어요.']),
 'lt': ('Sudėtinis būtasis (passato prossimo)', "avere arba essere esamuoju laiku + dalyvis (-ato, -uto, -ito: parlato, venduto, dormito).\n„Essere“ su judėjimo ir būsenos veiksmažodžiais (andare, venire, partire, nascere, restare) ir sangrąžiniais; tada dalyvis derinamas su veiksniu: Maria è andata.\nNetaisyklingi dalyviai: fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso.", ['Suvalgiau picą.', 'Nuvykome prie jūros.']),
 'tl': ('Ang passato prossimo', "avere o essere sa kasalukuyan + participle (-ato, -uto, -ito: parlato, venduto, dormito).\n«Essere» sa pandiwa ng galaw at kalagayan (andare, venire, partire, nascere, restare) at sa pandiwang pabalik; tumutugma noon ang participle sa simuno: Maria è andata.\nDi-regular na participle: fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso.", ['Kumain ako ng pizza.', 'Pumunta kami sa dagat.']),
},
'imperfetto': {
 'es': ('El imperfecto', "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano; prendevo; dormivo. essere: ero, eri, era, eravamo, eravate, erano. fare → facevo, dire → dicevo, bere → bevevo.\nDescribe un hábito, un decorado, una acción en curso; el passato prossimo cuenta el hecho: Mentre mangiavo, è arrivato Paolo.", ['De niño jugaba al fútbol.', 'Era tarde.']),
 'de': ('Das Imperfekt', "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano; prendevo; dormivo. essere: ero, eri, era, eravamo, eravate, erano. fare → facevo, dire → dicevo, bere → bevevo.\nEs beschreibt Gewohnheit, Hintergrund und laufende Handlung; das Perfekt erzählt das Ereignis: Mentre mangiavo, è arrivato Paolo.", ['Als Kind habe ich Fußball gespielt.', 'Es war spät.']),
 'pt': ('O imperfeito', "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano; prendevo; dormivo. essere: ero, eri, era, eravamo, eravate, erano. fare → facevo, dire → dicevo, bere → bevevo.\nDescreve hábito, cenário, ação em curso; o passato prossimo conta o acontecimento: Mentre mangiavo, è arrivato Paolo.", ['Quando criança, eu jogava futebol.', 'Era tarde.']),
 'ja': ('半過去', "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano、prendevo、dormivo。essere：ero, eri, era, eravamo, eravate, erano。fare → facevo、dire → dicevo、bere → bevevo。\n習慣・背景・進行中の動作を表し、近過去は起こった出来事を表します：Mentre mangiavo, è arrivato Paolo。", ['子供のころサッカーをしていました。', '遅い時間でした。']),
 'zh': ('未完成过去时', "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano；prendevo；dormivo。essere：ero, eri, era, eravamo, eravate, erano。fare → facevo，dire → dicevo，bere → bevevo。\n描述习惯、背景和进行中的动作；近过去时叙述发生的事件：Mentre mangiavo, è arrivato Paolo。", ['小时候我踢足球。', '那时已经很晚了。']),
 'ko': ('반과거', "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano, prendevo, dormivo. essere: ero, eri, era, eravamo, eravate, erano. fare → facevo, dire → dicevo, bere → bevevo.\n습관, 배경, 진행 중인 동작을 나타내고, 근과거는 일어난 사건을 이야기합니다: Mentre mangiavo, è arrivato Paolo.", ['어렸을 때 축구를 했어요.', '늦은 시간이었어요.']),
 'lt': ('Būtasis dažninis (imperfetto)', "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano; prendevo; dormivo. essere: ero, eri, era, eravamo, eravate, erano. fare → facevo, dire → dicevo, bere → bevevo.\nJis aprašo įprotį, foną, vykstantį veiksmą; passato prossimo pasakoja įvykį: Mentre mangiavo, è arrivato Paolo.", ['Vaikystėje žaisdavau futbolą.', 'Buvo vėlu.']),
 'tl': ('Ang imperfetto', "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano; prendevo; dormivo. essere: ero, eri, era, eravamo, eravate, erano. fare → facevo, dire → dicevo, bere → bevevo.\nInilalarawan nito ang gawi, tagpo at kilos na nangyayari; ang passato prossimo ang nagkukuwento ng pangyayari: Mentre mangiavo, è arrivato Paolo.", ['Noong bata ako, naglalaro ako ng futbol.', 'Gabi na noon.']),
},
'pronoms': {
 'es': ('Los pronombres complemento', "Directos: mi, ti, lo / la, ci, vi, li / le. Indirectos: mi, ti, gli / le, ci, vi, gli.\nVan delante del verbo conjugado (Lo vedo) o se unen al infinitivo (vederlo) y al imperativo (prendilo).\nCombinados: me lo, te lo, glielo, ce lo, ve lo. «Ne» sustituye a di + sustantivo o una cantidad (Ne voglio due); «ci» sustituye un lugar (Ci vado).", ['No lo sé.', 'Te quiero.']),
 'de': ('Objektpronomen', "Direkt: mi, ti, lo / la, ci, vi, li / le. Indirekt: mi, ti, gli / le, ci, vi, gli.\nSie stehen vor dem konjugierten Verb (Lo vedo) oder werden an Infinitiv (vederlo) und Imperativ (prendilo) angehängt.\nKombiniert: me lo, te lo, glielo, ce lo, ve lo. „Ne“ ersetzt di + Nomen oder eine Menge (Ne voglio due); „ci“ ersetzt einen Ort (Ci vado).", ['Ich weiß es nicht.', 'Ich liebe dich.']),
 'pt': ('Os pronomes complemento', "Diretos: mi, ti, lo / la, ci, vi, li / le. Indiretos: mi, ti, gli / le, ci, vi, gli.\nVêm antes do verbo conjugado (Lo vedo) ou ligam-se ao infinitivo (vederlo) e ao imperativo (prendilo).\nCombinados: me lo, te lo, glielo, ce lo, ve lo. «Ne» substitui di + substantivo ou uma quantidade (Ne voglio due); «ci» substitui um lugar (Ci vado).", ['Não sei.', 'Eu te amo.']),
 'ja': ('目的格代名詞', "直接目的語：mi, ti, lo / la, ci, vi, li / le。間接目的語：mi, ti, gli / le, ci, vi, gli。\n活用した動詞の前に置くか（Lo vedo）、不定詞（vederlo）や命令形（prendilo）の後ろにつけます。\n組み合わせ：me lo, te lo, glielo, ce lo, ve lo。ne は di + 名詞や数量の代わり（Ne voglio due）、ci は場所の代わり（Ci vado）。", ['知りません。', '愛してる。']),
 'zh': ('宾格代词', "直接宾语：mi, ti, lo / la, ci, vi, li / le。间接宾语：mi, ti, gli / le, ci, vi, gli。\n放在变位动词前（Lo vedo），或连在不定式（vederlo）和命令式（prendilo）后。\n组合：me lo, te lo, glielo, ce lo, ve lo。ne 代替 di + 名词或数量（Ne voglio due）；ci 代替地点（Ci vado）。", ['我不知道。', '我爱你。']),
 'ko': ('목적격 대명사', "직접 목적어: mi, ti, lo / la, ci, vi, li / le. 간접 목적어: mi, ti, gli / le, ci, vi, gli.\n활용된 동사 앞에 두거나(Lo vedo), 동사원형(vederlo)과 명령형(prendilo) 뒤에 붙입니다.\n결합형: me lo, te lo, glielo, ce lo, ve lo. ne는 di + 명사나 수량을 대신하고(Ne voglio due), ci는 장소를 대신합니다(Ci vado).", ['몰라요.', '사랑해.']),
 'lt': ('Papildinio įvardžiai', "Tiesioginiai: mi, ti, lo / la, ci, vi, li / le. Netiesioginiai: mi, ti, gli / le, ci, vi, gli.\nJie eina prieš asmenuojamą veiksmažodį (Lo vedo) arba prijungiami prie bendraties (vederlo) ir liepiamosios nuosakos (prendilo).\nJunginiai: me lo, te lo, glielo, ce lo, ve lo. „Ne“ pakeičia di + daiktavardį ar kiekį (Ne voglio due); „ci“ pakeičia vietą (Ci vado).", ['Nežinau.', 'Aš tave myliu.']),
 'tl': ('Mga panghalip na layon', "Tuwiran: mi, ti, lo / la, ci, vi, li / le. Di-tuwiran: mi, ti, gli / le, ci, vi, gli.\nInilalagay bago ang binanghay na pandiwa (Lo vedo) o idinidikit sa infinitive (vederlo) at pautos (prendilo).\nPinagsama: me lo, te lo, glielo, ce lo, ve lo. Pinapalitan ng «ne» ang di + pangngalan o dami (Ne voglio due); ng «ci» ang lugar (Ci vado).", ['Hindi ko alam.', 'Mahal kita.']),
},
'piacere-reflexifs': {
 'es': ('Piacere y los verbos pronominales', "«Piacere» funciona como «gustar»: Mi piace il gelato; Mi piacciono i gatti. A Marco piace leggere.\nPronominales: mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. En passato prossimo, siempre con essere: mi sono alzato.", ['Me gusta la música.', '¿Cómo te llamas?']),
 'de': ('Piacere und reflexive Verben', "„Piacere“ funktioniert wie „gefallen“: Mi piace il gelato; Mi piacciono i gatti. A Marco piace leggere.\nReflexive Verben: mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. Im Perfekt immer mit essere: mi sono alzato.", ['Ich mag Musik.', 'Wie heißt du?']),
 'pt': ('Piacere e os verbos pronominais', "«Piacere» funciona como «agradar»: Mi piace il gelato (gosto de sorvete); Mi piacciono i gatti. A Marco piace leggere.\nPronominais: mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. No passato prossimo, sempre com essere: mi sono alzato.", ['Gosto de música.', 'Como você se chama?']),
 'ja': ('piacere と再帰動詞', "piacere は「〜が気に入る」という形です：Mi piace il gelato（アイスが好き）、Mi piacciono i gatti。A Marco piace leggere。\n再帰動詞：mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano。近過去ではいつも essere：mi sono alzato。", ['音楽が好きです。', '名前は何ていうの？']),
 'zh': ('piacere 与自反动词', "piacere 的结构是「……让某人喜欢」：Mi piace il gelato（我喜欢冰淇淋）；Mi piacciono i gatti。A Marco piace leggere。\n自反动词：mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano。近过去时一律用 essere：mi sono alzato。", ['我喜欢音乐。', '你叫什么名字？']),
 'ko': ('piacere와 재귀 동사', "piacere는 「~가 마음에 들다」 구조입니다: Mi piace il gelato(아이스크림을 좋아해요), Mi piacciono i gatti. A Marco piace leggere.\n재귀 동사: mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. 근과거에서는 항상 essere: mi sono alzato.", ['음악을 좋아해요.', '이름이 뭐야?']),
 'lt': ('Piacere ir sangrąžiniai veiksmažodžiai', "„Piacere“ veikia kaip „patikti“: Mi piace il gelato; Mi piacciono i gatti. A Marco piace leggere.\nSangrąžiniai: mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. Passato prossimo visada su essere: mi sono alzato.", ['Man patinka muzika.', 'Kuo tu vardu?']),
 'tl': ('Piacere at mga pandiwang pabalik', "Ang «piacere» ay parang «magustuhan ng»: Mi piace il gelato (gusto ko ang gelato); Mi piacciono i gatti. A Marco piace leggere.\nPandiwang pabalik: mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. Sa passato prossimo, laging essere: mi sono alzato.", ['Gusto ko ang musika.', 'Ano ang pangalan mo?']),
},
'futur': {
 'es': ('El futuro', "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno (los verbos en -are cambian la a en e); prenderò; dormirò.\nRaíces irregulares: sarò (essere), avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò.\nEl futuro expresa también suposición: Sarà stanco (estará cansado). Para un plan cercano basta el presente: Domani parto.", ['Mañana lloverá.', 'Te llamaré esta noche.']),
 'de': ('Das Futur', "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno (Verben auf -are wandeln a in e); prenderò; dormirò.\nUnregelmäßige Stämme: sarò (essere), avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò.\nDas Futur drückt auch Vermutung aus: Sarà stanco (er wird wohl müde sein). Für nahe Pläne genügt das Präsens: Domani parto.", ['Morgen wird es regnen.', 'Ich rufe dich heute Abend an.']),
 'pt': ('O futuro', "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno (os verbos em -are mudam o a em e); prenderò; dormirò.\nRadicais irregulares: sarò (essere), avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò.\nO futuro também exprime suposição: Sarà stanco (deve estar cansado). Para um plano próximo basta o presente: Domani parto.", ['Amanhã vai chover.', 'Te ligo hoje à noite.']),
 'ja': ('未来形', "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno（-are 動詞は a が e に変わります）、prenderò、dormirò。\n不規則な語幹：sarò（essere）、avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò。\n未来形は推量も表します：Sarà stanco（疲れているのだろう）。近い予定なら現在形で十分です：Domani parto。", ['明日は雨が降るでしょう。', '今夜電話するね。']),
 'zh': ('将来时', "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno（-are 动词的 a 变成 e）；prenderò；dormirò。\n不规则词根：sarò（essere），avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò。\n将来时也表示推测：Sarà stanco（他大概累了）。近期计划用现在时即可：Domani parto。", ['明天会下雨。', '我今晚给你打电话。']),
 'ko': ('미래형', "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno(-are 동사는 a가 e로 바뀝니다), prenderò, dormirò.\n불규칙 어간: sarò(essere), avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò.\n미래형은 추측도 나타냅니다: Sarà stanco(피곤한가 봐요). 가까운 계획은 현재형으로 충분합니다: Domani parto.", ['내일 비가 올 거예요.', '오늘 밤에 전화할게.']),
 'lt': ('Būsimasis laikas', "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno (-are veiksmažodžių a virsta e); prenderò; dormirò.\nNetaisyklingi kamienai: sarò (essere), avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò.\nBūsimasis laikas reiškia ir spėjimą: Sarà stanco (turbūt pavargęs). Artimam planui užtenka esamojo: Domani parto.", ['Rytoj lis.', 'Paskambinsiu tau šįvakar.']),
 'tl': ('Ang hinaharap', "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno (nagiging e ang a sa pandiwang -are); prenderò; dormirò.\nDi-regular na ugat: sarò (essere), avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò.\nNagpapahayag din ng hula ang hinaharap: Sarà stanco (siguro pagod siya). Sa malapit na plano, sapat na ang kasalukuyan: Domani parto.", ['Uulan bukas.', 'Tatawagan kita mamayang gabi.']),
},
'conditionnel': {
 'es': ('El condicional', "La misma raíz que el futuro + ei, esti, ebbe, emmo, este, ebbero: parlerei, saresti, avrebbe, vorremmo.\nCortesía: Vorrei un caffè. Potrebbe aiutarmi? Consejo: Dovresti riposare.\nCompuesto: avrei / sarei + participio (Sarei venuto); es también el «futuro en el pasado»: Ha detto che sarebbe venuto.", ['Quisiera un vaso de agua.', 'Deberías dormir más.']),
 'de': ('Das Konditional', "Derselbe Stamm wie im Futur + ei, esti, ebbe, emmo, este, ebbero: parlerei, saresti, avrebbe, vorremmo.\nHöflichkeit: Vorrei un caffè. Potrebbe aiutarmi? Rat: Dovresti riposare.\nVergangenheit: avrei / sarei + Partizip (Sarei venuto); auch für die Zukunft in der Vergangenheit: Ha detto che sarebbe venuto.", ['Ich hätte gern ein Glas Wasser.', 'Du solltest mehr schlafen.']),
 'pt': ('O condicional', "O mesmo radical do futuro + ei, esti, ebbe, emmo, este, ebbero: parlerei, saresti, avrebbe, vorremmo.\nCortesia: Vorrei un caffè. Potrebbe aiutarmi? Conselho: Dovresti riposare.\nComposto: avrei / sarei + particípio (Sarei venuto); é também o «futuro do passado»: Ha detto che sarebbe venuto (disse que viria).", ['Eu queria um copo de água.', 'Você deveria dormir mais.']),
 'ja': ('条件法', "未来形と同じ語幹 + ei, esti, ebbe, emmo, este, ebbero：parlerei, saresti, avrebbe, vorremmo。\n丁寧な表現：Vorrei un caffè. Potrebbe aiutarmi? 助言：Dovresti riposare。\n過去：avrei / sarei + 過去分詞（Sarei venuto）。過去から見た未来にも使います：Ha detto che sarebbe venuto。", ['水を一杯ください。', 'もっと寝たほうがいいよ。']),
 'zh': ('条件式', "与将来时相同的词根 + ei, esti, ebbe, emmo, este, ebbero：parlerei, saresti, avrebbe, vorremmo。\n礼貌：Vorrei un caffè. Potrebbe aiutarmi? 建议：Dovresti riposare。\n复合形式：avrei / sarei + 过去分词（Sarei venuto）；也表示过去将来：Ha detto che sarebbe venuto。", ['我想要一杯水。', '你应该多睡一点。']),
 'ko': ('조건법', "미래형과 같은 어간 + ei, esti, ebbe, emmo, este, ebbero: parlerei, saresti, avrebbe, vorremmo.\n공손: Vorrei un caffè. Potrebbe aiutarmi? 조언: Dovresti riposare.\n과거: avrei / sarei + 과거분사(Sarei venuto). 과거에서 본 미래에도 씁니다: Ha detto che sarebbe venuto.", ['물 한 잔 주세요.', '더 자야 해.']),
 'lt': ('Tariamoji nuosaka', "Tas pats kamienas kaip būsimajame + ei, esti, ebbe, emmo, este, ebbero: parlerei, saresti, avrebbe, vorremmo.\nMandagumas: Vorrei un caffè. Potrebbe aiutarmi? Patarimas: Dovresti riposare.\nSudėtinė: avrei / sarei + dalyvis (Sarei venuto); taip pat „ateitis praeityje“: Ha detto che sarebbe venuto.", ['Norėčiau stiklinės vandens.', 'Turėtum daugiau miegoti.']),
 'tl': ('Ang kondisyonal', "Parehong ugat ng hinaharap + ei, esti, ebbe, emmo, este, ebbero: parlerei, saresti, avrebbe, vorremmo.\nPaggalang: Vorrei un caffè. Potrebbe aiutarmi? Payo: Dovresti riposare.\nTambalan: avrei / sarei + participle (Sarei venuto); ito rin ang «hinaharap sa nakaraan»: Ha detto che sarebbe venuto.", ['Isang basong tubig nga po.', 'Dapat mas matagal kang matulog.']),
},
'imperatif': {
 'es': ('El imperativo', "Tu: parla, prendi, dormi (finisci). Noi: parliamo. Voi: parlate. Lei (cortesía): subjuntivo — parli, prenda, dorma.\nIrregulares en tu: va', fa', di', da', sta', sii, abbi, vieni.\nNegación en tu: non + infinitivo (Non parlare!). Los pronombres se unen: dimmi, fallo, alzati; con Lei van delante: mi dica.", ['¡Ven aquí!', 'No te preocupes.']),
 'de': ('Der Imperativ', "Tu: parla, prendi, dormi (finisci). Noi: parliamo. Voi: parlate. Lei (Höflichkeit): Konjunktiv — parli, prenda, dorma.\nUnregelmäßig bei tu: va', fa', di', da', sta', sii, abbi, vieni.\nVerneinung bei tu: non + Infinitiv (Non parlare!). Pronomen werden angehängt: dimmi, fallo, alzati; bei Lei stehen sie davor: mi dica.", ['Komm her!', 'Mach dir keine Sorgen.']),
 'pt': ('O imperativo', "Tu: parla, prendi, dormi (finisci). Noi: parliamo. Voi: parlate. Lei (cortesia): subjuntivo — parli, prenda, dorma.\nIrregulares em tu: va', fa', di', da', sta', sii, abbi, vieni.\nNegação em tu: non + infinitivo (Non parlare!). Os pronomes ligam-se: dimmi, fallo, alzati; com Lei vêm antes: mi dica.", ['Venha aqui!', 'Não se preocupe.']),
 'ja': ('命令形', "tu：parla, prendi, dormi（finisci）。noi：parliamo。voi：parlate。Lei（敬称）は接続法：parli, prenda, dorma。\ntu の不規則形：va', fa', di', da', sta', sii, abbi, vieni。\ntu の否定命令は non + 不定詞（Non parlare!）。代名詞は後ろにつけます：dimmi, fallo, alzati。Lei では前に置きます：mi dica。", ['こっちに来て！', '心配しないで。']),
 'zh': ('命令式', "tu：parla, prendi, dormi（finisci）。noi：parliamo。voi：parlate。Lei（尊称）用虚拟式：parli, prenda, dorma。\ntu 的不规则形式：va', fa', di', da', sta', sii, abbi, vieni。\ntu 的否定：non + 不定式（Non parlare!）。代词连写在后：dimmi, fallo, alzati；用 Lei 时放在前面：mi dica。", ['过来！', '别担心。']),
 'ko': ('명령형', "tu: parla, prendi, dormi(finisci). noi: parliamo. voi: parlate. Lei(존칭)는 접속법: parli, prenda, dorma.\ntu의 불규칙형: va', fa', di', da', sta', sii, abbi, vieni.\ntu의 부정 명령: non + 동사원형(Non parlare!). 대명사는 뒤에 붙입니다: dimmi, fallo, alzati. Lei에서는 앞에 둡니다: mi dica.", ['이리 와!', '걱정하지 마.']),
 'lt': ('Liepiamoji nuosaka', "Tu: parla, prendi, dormi (finisci). Noi: parliamo. Voi: parlate. Lei (mandagiai): konjunktyvas — parli, prenda, dorma.\nNetaisyklingi su tu: va', fa', di', da', sta', sii, abbi, vieni.\nNeiginys su tu: non + bendratis (Non parlare!). Įvardžiai prijungiami: dimmi, fallo, alzati; su Lei eina prieš: mi dica.", ['Ateik čia!', 'Nesijaudink.']),
 'tl': ('Ang pautos', "Tu: parla, prendi, dormi (finisci). Noi: parliamo. Voi: parlate. Lei (magalang): congiuntivo — parli, prenda, dorma.\nDi-regular sa tu: va', fa', di', da', sta', sii, abbi, vieni.\nNegatibo sa tu: non + infinitive (Non parlare!). Idinidikit ang panghalip: dimmi, fallo, alzati; sa Lei, nasa unahan: mi dica.", ['Halika rito!', 'Huwag kang mag-alala.']),
},
'comparaison-relatifs': {
 'es': ('Comparar y enlazar', "più … di, meno … di ante un sustantivo o pronombre (più alto di me); «che» para comparar dos adjetivos, verbos o complementos (più bello che utile). Igualdad: (così) … come, (tanto) … quanto. Irregulares: migliore, peggiore, maggiore, minore; meglio, peggio. Superlativo: il più bello; bellissimo.\nRelativos: che (sujeto y complemento), cui tras preposición (la città in cui vivo), il quale; chi = el que.", ['Es más alto que yo.', 'El libro que leo es interesante.']),
 'de': ('Vergleichen und verbinden', "più … di, meno … di vor Nomen oder Pronomen (più alto di me); „che“, um zwei Adjektive, Verben oder Ergänzungen zu vergleichen (più bello che utile). Gleichheit: (così) … come, (tanto) … quanto. Unregelmäßig: migliore, peggiore, maggiore, minore; meglio, peggio. Superlativ: il più bello; bellissimo.\nRelativpronomen: che (Subjekt und Objekt), cui nach Präposition (la città in cui vivo), il quale; chi = wer.", ['Er ist größer als ich.', 'Das Buch, das ich lese, ist interessant.']),
 'pt': ('Comparar e ligar', "più … di, meno … di antes de substantivo ou pronome (più alto di me); «che» para comparar dois adjetivos, verbos ou complementos (più bello che utile). Igualdade: (così) … come, (tanto) … quanto. Irregulares: migliore, peggiore, maggiore, minore; meglio, peggio. Superlativo: il più bello; bellissimo.\nRelativos: che (sujeito e objeto), cui depois de preposição (la città in cui vivo), il quale; chi = quem.", ['Ele é mais alto do que eu.', 'O livro que leio é interessante.']),
 'ja': ('比較と関係詞', "名詞・代名詞の前では più … di、meno … di（più alto di me）。形容詞・動詞・補語どうしを比べるときは che（più bello che utile）。同等：(così) … come、(tanto) … quanto。不規則：migliore, peggiore, maggiore, minore、meglio, peggio。最上級：il più bello、bellissimo。\n関係詞：che（主語・目的語）、前置詞の後は cui（la città in cui vivo）、il quale。chi = 〜する人。", ['彼は私より背が高いです。', '私が読んでいる本はおもしろいです。']),
 'zh': ('比较与关系词', "在名词或代词前用 più … di、meno … di（più alto di me）；比较两个形容词、动词或补语时用 che（più bello che utile）。同级：(così) … come，(tanto) … quanto。不规则：migliore, peggiore, maggiore, minore；meglio, peggio。最高级：il più bello；bellissimo。\n关系词：che（主语和宾语），介词后用 cui（la città in cui vivo），il quale；chi = ……的人。", ['他比我高。', '我在读的书很有意思。']),
 'ko': ('비교와 관계사', "명사·대명사 앞에서는 più … di, meno … di(più alto di me). 형용사, 동사, 보어끼리 비교할 때는 che(più bello che utile). 동등: (così) … come, (tanto) … quanto. 불규칙: migliore, peggiore, maggiore, minore, meglio, peggio. 최상급: il più bello, bellissimo.\n관계사: che(주어와 목적어), 전치사 뒤에는 cui(la città in cui vivo), il quale, chi = ~하는 사람.", ['그는 저보다 키가 커요.', '제가 읽는 책은 재미있어요.']),
 'lt': ('Lyginimas ir jungimas', "più … di, meno … di prieš daiktavardį ar įvardį (più alto di me); „che“, kai lyginami du būdvardžiai, veiksmažodžiai ar papildiniai (più bello che utile). Lygybė: (così) … come, (tanto) … quanto. Netaisyklingi: migliore, peggiore, maggiore, minore; meglio, peggio. Aukščiausiasis: il più bello; bellissimo.\nSantykiniai: che (veiksnys ir papildinys), cui po prielinksnio (la città in cui vivo), il quale; chi = kas.", ['Jis aukštesnis už mane.', 'Knyga, kurią skaitau, įdomi.']),
 'tl': ('Paghahambing at pag-uugnay', "più … di, meno … di bago pangngalan o panghalip (più alto di me); «che» kapag dalawang pang-uri, pandiwa o kaganapan ang inihahambing (più bello che utile). Pagkakapantay: (così) … come, (tanto) … quanto. Di-regular: migliore, peggiore, maggiore, minore; meglio, peggio. Pinakamataas: il più bello; bellissimo.\nPang-ugnay: che (simuno at layon), cui pagkatapos ng pang-ukol (la città in cui vivo), il quale; chi = sinumang.", ['Mas matangkad siya sa akin.', 'Kawili-wili ang librong binabasa ko.']),
},
'congiuntivo': {
 'es': ('El subjuntivo presente', "parli, parli, parli, parliamo, parliate, parlino; prenda… prendano; dorma… dormano. Irregulares: sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica.\nTras verbos de opinión, duda, deseo y emoción: Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia. También tras benché, affinché, prima che, a meno che.\nSi los dos sujetos son el mismo: di + infinitivo (Penso di partire).\nAtención: a diferencia del español, el italiano usa el subjuntivo incluso tras «creo que».", ['Creo que tienes razón.', 'Espero que estéis bien.']),
 'de': ('Der Konjunktiv Präsens (congiuntivo)', "parli, parli, parli, parliamo, parliate, parlino; prenda… prendano; dorma… dormano. Unregelmäßig: sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica.\nNach Verben der Meinung, des Zweifels, des Wunsches und des Gefühls: Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia. Auch nach benché, affinché, prima che, a meno che.\nBei gleichem Subjekt: di + Infinitiv (Penso di partire).", ['Ich glaube, du hast recht.', 'Ich hoffe, es geht euch gut.']),
 'pt': ('O presente do subjuntivo (congiuntivo)', "parli, parli, parli, parliamo, parliate, parlino; prenda… prendano; dorma… dormano. Irregulares: sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica.\nDepois de verbos de opinião, dúvida, desejo e emoção: Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia. Também depois de benché, affinché, prima che, a meno che.\nSe os dois sujeitos forem o mesmo: di + infinitivo (Penso di partire).\nAtenção: ao contrário do português, usa-se o subjuntivo até depois de «acho que».", ['Acho que você tem razão.', 'Espero que vocês estejam bem.']),
 'ja': ('接続法現在', "parli, parli, parli, parliamo, parliate, parlino、prenda… prendano、dorma… dormano。不規則：sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica。\n意見・疑い・願望・感情を表す動詞の後：Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia。benché, affinché, prima che, a meno che の後でも使います。\n主語が同じときは di + 不定詞（Penso di partire）。", ['あなたは正しいと思います。', 'みんな元気だといいな。']),
 'zh': ('虚拟式现在时', "parli, parli, parli, parliamo, parliate, parlino；prenda… prendano；dorma… dormano。不规则：sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica。\n用于表示看法、怀疑、愿望和情感的动词后：Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia。也用于 benché, affinché, prima che, a meno che 之后。\n主语相同时：di + 不定式（Penso di partire）。", ['我认为你是对的。', '希望你们都好。']),
 'ko': ('접속법 현재', "parli, parli, parli, parliamo, parliate, parlino, prenda… prendano, dorma… dormano. 불규칙: sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica.\n의견, 의심, 바람, 감정을 나타내는 동사 뒤: Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia. benché, affinché, prima che, a meno che 뒤에서도 씁니다.\n주어가 같으면 di + 동사원형(Penso di partire).", ['네 말이 맞는 것 같아.', '다들 잘 지내길 바라.']),
 'lt': ('Konjunktyvo esamasis laikas', "parli, parli, parli, parliamo, parliate, parlino; prenda… prendano; dorma… dormano. Netaisyklingi: sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica.\nPo nuomonės, abejonės, noro ir jausmo veiksmažodžių: Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia. Taip pat po benché, affinché, prima che, a meno che.\nKai veiksnys tas pats: di + bendratis (Penso di partire).", ['Manau, kad tu teisus.', 'Tikiuosi, kad jums gerai sekasi.']),
 'tl': ('Ang congiuntivo sa kasalukuyan', "parli, parli, parli, parliamo, parliate, parlino; prenda… prendano; dorma… dormano. Di-regular: sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica.\nPagkatapos ng pandiwa ng opinyon, pag-aalinlangan, hangarin at damdamin: Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia. Gayundin pagkatapos ng benché, affinché, prima che, a meno che.\nKung iisa ang simuno: di + infinitive (Penso di partire).", ['Sa tingin ko tama ka.', 'Sana mabuti kayo.']),
},
'ipotetico': {
 'es': ('El imperfecto de subjuntivo y la hipótesis', "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero; essere: fossi, fosse, fossero; avere: avessi; fare: facessi.\nHipótesis posible o irreal: se + imperfecto de subjuntivo, condicional. Se avessi tempo, viaggerei.\nIrreal del pasado: Se avessi saputo, sarei venuto.\nCondición real: indicativo en las dos partes. Se piove, resto a casa.", ['Si fuera rico, compraría un barco.']),
 'de': ('Der Konjunktiv Imperfekt und der Bedingungssatz', "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero; essere: fossi, fosse, fossero; avere: avessi; fare: facessi.\nMögliche oder irreale Bedingung: se + Konjunktiv Imperfekt, Konditional. Se avessi tempo, viaggerei.\nIrreale Vergangenheit: Se avessi saputo, sarei venuto.\nReale Bedingung: Indikativ auf beiden Seiten. Se piove, resto a casa.", ['Wenn ich reich wäre, würde ich ein Boot kaufen.']),
 'pt': ('O imperfeito do subjuntivo e a hipótese', "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero; essere: fossi, fosse, fossero; avere: avessi; fare: facessi.\nHipótese possível ou irreal: se + imperfeito do subjuntivo, condicional. Se avessi tempo, viaggerei.\nIrreal do passado: Se avessi saputo, sarei venuto.\nCondição real: indicativo nas duas partes. Se piove, resto a casa.", ['Se eu fosse rico, compraria um barco.']),
 'ja': ('接続法半過去と仮定文', "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero。essere：fossi, fosse, fossero。avere：avessi。fare：facessi。\n可能性の低い・事実に反する仮定：se + 接続法半過去、条件法。Se avessi tempo, viaggerei。\n過去の事実に反する仮定：Se avessi saputo, sarei venuto。\n現実的な条件では両方とも直説法：Se piove, resto a casa。", ['お金持ちならボートを買うのに。']),
 'zh': ('虚拟式未完成过去时与假设句', "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero；essere：fossi, fosse, fossero；avere：avessi；fare：facessi。\n可能性小或非真实的假设：se + 虚拟式未完成过去时，条件式。Se avessi tempo, viaggerei。\n与过去事实相反：Se avessi saputo, sarei venuto。\n真实条件两边都用直陈式：Se piove, resto a casa。", ['如果我有钱，我就买一条船。']),
 'ko': ('접속법 반과거와 가정문', "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero, essere: fossi, fosse, fossero, avere: avessi, fare: facessi.\n가능성이 낮거나 사실과 반대되는 가정: se + 접속법 반과거, 조건법. Se avessi tempo, viaggerei.\n과거 사실과 반대: Se avessi saputo, sarei venuto.\n현실적인 조건은 양쪽 다 직설법: Se piove, resto a casa.", ['부자라면 배를 살 텐데.']),
 'lt': ('Konjunktyvo būtasis ir sąlygos sakinys', "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero; essere: fossi, fosse, fossero; avere: avessi; fare: facessi.\nGalima ar nereali sąlyga: se + konjunktyvo būtasis, tariamoji nuosaka. Se avessi tempo, viaggerei.\nNereali praeitis: Se avessi saputo, sarei venuto.\nReali sąlyga: tiesioginė nuosaka abiejose dalyse. Se piove, resto a casa.", ['Jei būčiau turtingas, nusipirkčiau valtį.']),
 'tl': ('Congiuntivo sa nakaraan at hinuha', "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero; essere: fossi, fosse, fossero; avere: avessi; fare: facessi.\nPosible o di-totoong kondisyon: se + congiuntivo sa nakaraan, kondisyonal. Se avessi tempo, viaggerei.\nDi-totoo sa nakaraan: Se avessi saputo, sarei venuto.\nTotoong kondisyon: indikatibo sa dalawang bahagi. Se piove, resto a casa.", ['Kung mayaman ako, bibili ako ng bangka.']),
},
'passato-remoto': {
 'es': ('El pretérito indefinido (passato remoto) y la pasiva', "Tiempo de la narración escrita y de la historia, frecuente al hablar en el sur: parlai, parlasti, parlò, parlammo, parlaste, parlarono. Irregulares: fui, fu, furono (essere); ebbi, ebbe; feci, fece; dissi, disse; venni, venne; vidi, vide.\nPasiva: essere (o venire) + participio concordado + da. Il libro è stato scritto da Eco. «Si» impersonal: In Italia si mangia bene.", ['Dante nació en Florencia.', 'Aquí se habla italiano.']),
 'de': ('Das Passato remoto und das Passiv', "Zeit der schriftlichen Erzählung und der Geschichte, im Süden auch mündlich häufig: parlai, parlasti, parlò, parlammo, parlaste, parlarono. Unregelmäßig: fui, fu, furono (essere); ebbi, ebbe; feci, fece; dissi, disse; venni, venne; vidi, vide.\nPassiv: essere (oder venire) + angeglichenes Partizip + da. Il libro è stato scritto da Eco. Unpersönliches „si“: In Italia si mangia bene.", ['Dante wurde in Florenz geboren.', 'Hier spricht man Italienisch.']),
 'pt': ('O passato remoto e a passiva', "Tempo da narração escrita e da história, frequente na fala no sul: parlai, parlasti, parlò, parlammo, parlaste, parlarono. Irregulares: fui, fu, furono (essere); ebbi, ebbe; feci, fece; dissi, disse; venni, venne; vidi, vide.\nPassiva: essere (ou venire) + particípio concordado + da. Il libro è stato scritto da Eco. «Si» impessoal: In Italia si mangia bene.", ['Dante nasceu em Florença.', 'Aqui se fala italiano.']),
 'ja': ('遠過去と受動態', "書き言葉の物語や歴史で使う時制で、南部では話し言葉でもよく使います：parlai, parlasti, parlò, parlammo, parlaste, parlarono。不規則：fui, fu, furono（essere）、ebbi, ebbe、feci, fece、dissi, disse、venni, venne、vidi, vide。\n受動態：essere（または venire）+ 性数一致した過去分詞 + da。Il libro è stato scritto da Eco。非人称の si：In Italia si mangia bene。", ['ダンテはフィレンツェで生まれました。', 'ここではイタリア語が話されています。']),
 'zh': ('远过去时与被动语态', "书面叙事和历史中使用的时态，南方口语中也常用：parlai, parlasti, parlò, parlammo, parlaste, parlarono。不规则：fui, fu, furono（essere）；ebbi, ebbe；feci, fece；dissi, disse；venni, venne；vidi, vide。\n被动语态：essere（或 venire）+ 性数一致的过去分词 + da。Il libro è stato scritto da Eco。无人称 si：In Italia si mangia bene。", ['但丁出生于佛罗伦萨。', '这里说意大利语。']),
 'ko': ('원과거와 수동태', "글로 쓴 이야기와 역사에 쓰는 시제로, 남부에서는 말할 때도 자주 씁니다: parlai, parlasti, parlò, parlammo, parlaste, parlarono. 불규칙: fui, fu, furono(essere), ebbi, ebbe, feci, fece, dissi, disse, venni, venne, vidi, vide.\n수동태: essere(또는 venire) + 성수 일치한 과거분사 + da. Il libro è stato scritto da Eco. 비인칭 si: In Italia si mangia bene.", ['단테는 피렌체에서 태어났어요.', '여기서는 이탈리아어를 써요.']),
 'lt': ('Passato remoto ir neveikiamoji rūšis', "Rašytinio pasakojimo ir istorijos laikas, pietuose dažnas ir šnekant: parlai, parlasti, parlò, parlammo, parlaste, parlarono. Netaisyklingi: fui, fu, furono (essere); ebbi, ebbe; feci, fece; dissi, disse; venni, venne; vidi, vide.\nNeveikiamoji: essere (arba venire) + suderintas dalyvis + da. Il libro è stato scritto da Eco. Beasmenis „si“: In Italia si mangia bene.", ['Dantė gimė Florencijoje.', 'Čia kalbama itališkai.']),
 'tl': ('Ang passato remoto at balintiyak', "Panahunan ng nakasulat na salaysay at kasaysayan, madalas din sa usapan sa timog: parlai, parlasti, parlò, parlammo, parlaste, parlarono. Di-regular: fui, fu, furono (essere); ebbi, ebbe; feci, fece; dissi, disse; venni, venne; vidi, vide.\nBalintiyak: essere (o venire) + tumutugmang participle + da. Il libro è stato scritto da Eco. Impersonal na «si»: In Italia si mangia bene.", ['Ipinanganak si Dante sa Florence.', 'Italyano ang sinasalita rito.']),
},
}
